<script setup>
defineProps({product:Object,draft:Object,errors:Object,categories:Array,editing:Boolean})
defineEmits(['form','save','dirty'])
</script>
<template><p v-if="editing&&!product">{{ $t("Produit introuvable.") }}</p><form v-else  :ref="el=>$emit('form',el)" class="admin-card admin-form" @submit.prevent="$emit('save')" @input="$emit('dirty')" @change="$emit('dirty')" novalidate><label v-for="[key,label] in [['name','Nom'],['price','Prix en euros'],['stock','Stock']]" :key="key" :for="'admin-'+key">{{ $t(label) }}<input :id="'admin-'+key" :aria-label="$t(label)" v-model="draft[key]" :maxlength="key==='name'?100:12" :inputmode="key==='name'?'text':'decimal'" :aria-invalid="Boolean(errors[key])" :aria-describedby="'error-'+key" required/><span :id="'error-'+key" class="field-error">{{ $t(errors[key]) }}</span></label><label for="admin-category">{{ $t("Catégorie") }}<select id="admin-category" v-model="draft.category" :aria-invalid="Boolean(errors.category)" aria-describedby="error-category"><option value="">{{ $t("Choisir") }}</option><option v-for="item in categories" :key="item.id" :value="item.name">{{ $t(item.name) }}</option></select><span id="error-category" class="field-error">{{ $t(errors.category) }}</span></label><p>{{ $t("Création en brouillon. Les photos et variantes réelles seront gérées après intégration de la médiathèque et du modèle de variantes sécurisé côté serveur.") }}</p><button class="button button-dark">{{ $t("Enregistrer la simulation") }}</button><RouterLink :to="{name:'admin-products'}">{{ $t("Annuler") }}</RouterLink></form></template>
